#[unsafe(no_mangle)]
pub unsafe extern "C" fn ibx_req_mkt_data(h: *mut IbxClient, req_id: i64, contract: IbxStr, generic_ticks: IbxStr, snapshot: bool, regulatory_snaphsot: bool) -> i32 {
    crate::capi::request(h, |c, w| {
        let _ = &w;
        let mut rd = R::new(unsafe { contract.bytes() });
        let contract = r_contract(&mut rd);
        if let Some((code, text)) = rd.refused { return crate::capi::refuse(c, req_id, code, text); }
        let generic_ticks = unsafe { generic_ticks.text() };
        let generic_ticks = &*generic_ticks;
        (c.req_mkt_data(req_id, &contract, generic_ticks, snapshot, regulatory_snaphsot)).status()
    })
}

