    pub(crate) fn check_contract(x: &crate::api::types::Contract, seed: i64, path: &str, out: &mut Vec<String>) {
        expect(out, format!("{path}.conId"), x.con_id as i64 == tv_i("conId", seed));
        expect(out, format!("{path}.symbol"), x.symbol == tv_s("symbol", seed));
        expect(out, format!("{path}.secType"), x.sec_type == tv_s("secType", seed));
        expect(out, format!("{path}.lastTradeDateOrContractMonth"), x.last_trade_date_or_contract_month == tv_s("lastTradeDateOrContractMonth", seed));
        expect(out, format!("{path}.lastTradeDate"), x.last_trade_date == tv_s("lastTradeDate", seed));
        expect(out, format!("{path}.right"), x.right == tv_s("right", seed));
        expect(out, format!("{path}.multiplier"), x.multiplier == tv_s("multiplier", seed));
        expect(out, format!("{path}.exchange"), x.exchange == tv_s("exchange", seed));
        expect(out, format!("{path}.primaryExchange"), x.primary_exchange == tv_s("primaryExchange", seed));
        expect(out, format!("{path}.currency"), x.currency == tv_s("currency", seed));
        expect(out, format!("{path}.localSymbol"), x.local_symbol == tv_s("localSymbol", seed));
        expect(out, format!("{path}.tradingClass"), x.trading_class == tv_s("tradingClass", seed));
        expect(out, format!("{path}.includeExpired"), x.include_expired == tv_b("includeExpired", seed));
        expect(out, format!("{path}.secIdType"), x.sec_id_type == tv_s("secIdType", seed));
        expect(out, format!("{path}.secId"), x.sec_id == tv_s("secId", seed));
        expect(out, format!("{path}.description"), x.description == tv_s("description", seed));
        expect(out, format!("{path}.issuerId"), x.issuer_id == tv_s("issuerId", seed));
        expect(out, format!("{path}.comboLegsDescrip"), x.combo_legs_descrip == tv_s("comboLegsDescrip", seed));
        expect(out, format!("{path}.comboLegs"), x.combo_legs.len() == 2); for (k, e) in x.combo_legs.iter().enumerate() { check_combo_leg(e, seed + 1 + k as i64, &format!("{path}.comboLegs"), out); }
        expect(out, format!("{path}.deltaNeutralContract"), x.delta_neutral_contract.is_some()); if let Some(e) = &x.delta_neutral_contract { check_delta_neutral_contract(e, seed + 1, &format!("{path}.deltaNeutralContract"), out); }
    }

